/* Themed single-select menus with native form values behind the visible control. */
let selectSequence=0,activeSelect=null;
function selectChevron(){return '<svg class="select-chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg>';}
function selectControl({name='',options,value='',attributes={},label=''}){
 const id='shared-select-'+(++selectSequence),items=options.map(option=>typeof option==='object'?option:{value:option,label:option}),selected=items.find(item=>String(item.value)===String(value))||items[0],attrs=Object.entries(attributes).filter(([key])=>/^(data-[\w-]+|aria-[\w-]+|id|required|disabled)$/.test(key)).map(([key,val])=>val===true?key:val===false||val==null?'':`${key}="${escape(val)}"`).filter(Boolean).join(' ');
 return `<span class="select-control"><select hidden aria-hidden="true" tabindex="-1" data-select-native ${name?`name="${escape(name)}"`:''} ${attrs}>${items.map(item=>`<option value="${escape(item.value)}" ${item===selected?'selected':''} ${item.disabled?'disabled':''}>${escape(item.label)}</option>`).join('')}</select><button type="button" id="${id}" role="combobox" aria-label="${escape(attributes['aria-label']||label||name)}" aria-haspopup="listbox" aria-expanded="false" data-select-trigger ${attributes.disabled?'disabled':''}><span class="select-value">${escape(selected?.label||'Choose an option')}</span>${selectChevron()}</button></span>`;
}
function selectField({label,className='',...config}){const control=selectControl({...config,label}),id='shared-select-'+selectSequence;return `<div class="select-field ${escape(className)}"><label for="${id}">${escape(label)}</label>${control}</div>`;}
function syncSelectControls(){document.querySelectorAll('[data-select-native]').forEach(native=>{const trigger=native.parentElement.querySelector('[data-select-trigger]');trigger.querySelector('.select-value').textContent=native.selectedOptions[0]?.textContent||'Choose an option';trigger.disabled=native.disabled;});}
function closeSelectMenu(returnFocus=true){if(!activeSelect)return;const {trigger,overlay}=activeSelect;overlay.remove();trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-controls');trigger.removeAttribute('aria-activedescendant');activeSelect=null;if(returnFocus&&trigger.isConnected)trigger.focus();}
function highlightSelect(index){if(!activeSelect)return;const {native,trigger,overlay}=activeSelect,options=[...native.options];if(!options.length)return;let next=(index+options.length)%options.length;for(let tries=0;tries<options.length&&options[next].disabled;tries++)next=(next+1)%options.length;activeSelect.index=next;overlay.querySelectorAll('[data-select-option]').forEach((item,i)=>item.classList.toggle('is-highlighted',i===next));const option=overlay.querySelector(`[data-select-option="${next}"]`);trigger.setAttribute('aria-activedescendant',option.id);option.scrollIntoView({block:'nearest'});}
function openSelectMenu(trigger){if(activeSelect?.trigger===trigger){closeSelectMenu();return;}closeSelectMenu(false);const native=trigger.parentElement.querySelector('[data-select-native]'),phone=trigger.closest('.phone');if(!phone||native.disabled)return;const p=phone.getBoundingClientRect(),r=trigger.getBoundingClientRect(),style=getComputedStyle(phone),scale=p.width/phone.offsetWidth,borderLeft=parseFloat(style.borderLeftWidth)||0,borderTop=parseFloat(style.borderTopWidth)||0,triggerLeft=(r.left-p.left)/scale-borderLeft,triggerTop=(r.top-p.top)/scale-borderTop,triggerBottom=(r.bottom-p.top)/scale-borderTop,width=Math.min(r.width/scale,phone.clientWidth-32),left=Math.max(16,Math.min(triggerLeft,phone.clientWidth-width-16)),below=phone.clientHeight-triggerBottom-18,above=triggerTop-18,desired=Math.min(native.options.length*42+12,260),useAbove=below<desired&&above>below,maxHeight=Math.max(84,Math.min(260,useAbove?above:below)),overlay=document.createElement('div'),listId=trigger.id+'-options';overlay.className='select-menu-overlay';overlay.innerHTML=`<div class="select-dismiss" data-select-dismiss></div><div class="themed-select-menu" id="${listId}" role="listbox" aria-label="${escape(trigger.getAttribute('aria-label'))} options" style="left:${left}px;width:${width}px;max-height:${maxHeight}px;${useAbove?'bottom:'+Math.max(16,phone.clientHeight-triggerTop+6)+'px':'top:'+(triggerBottom+6)+'px'}">${[...native.options].map((option,i)=>`<button type="button" role="option" tabindex="-1" id="${listId}-${i}" data-select-option="${i}" aria-selected="${i===native.selectedIndex}" ${option.disabled?'disabled aria-disabled="true"':''}><span>${escape(option.textContent)}</span><svg class="select-option-check" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4 10-10"/></svg></button>`).join('')}</div>`;phone.append(overlay);activeSelect={native,trigger,overlay,index:native.selectedIndex,typed:'',typedAt:0};trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls',listId);trigger.focus();highlightSelect(Math.max(0,native.selectedIndex));}
function chooseSelect(index){if(!activeSelect)return;const {native}=activeSelect;if(!native.options[index]||native.options[index].disabled)return;native.selectedIndex=index;syncSelectControls();closeSelectMenu();native.dispatchEvent(new Event('change',{bubbles:true}));}
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-select-trigger]'),option=event.target.closest('[data-select-option]');if(trigger){event.preventDefault();openSelectMenu(trigger);}else if(option){event.preventDefault();chooseSelect(Number(option.dataset.selectOption));}else if(event.target.closest('[data-select-dismiss]'))closeSelectMenu();});
document.addEventListener('change',event=>{if(event.target.matches('[data-select-native]'))syncSelectControls();});
document.addEventListener('keydown',event=>{const trigger=event.target.closest('[data-select-trigger]');if(!trigger&&!activeSelect)return;if(!activeSelect){if(['ArrowDown','ArrowUp','Enter',' '].includes(event.key)){event.preventDefault();openSelectMenu(trigger);}return;}if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closeSelectMenu();}else if(event.key==='Tab')closeSelectMenu(false);else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();highlightSelect(event.key==='Home'?0:event.key==='End'?activeSelect.native.options.length-1:activeSelect.index+(event.key==='ArrowDown'?1:-1));}else if(event.key==='Enter'||event.key===' '){event.preventDefault();chooseSelect(activeSelect.index);}else if(event.key.length===1&&!event.ctrlKey&&!event.metaKey){const now=Date.now();activeSelect.typed=now-activeSelect.typedAt>700?event.key:activeSelect.typed+event.key;activeSelect.typedAt=now;const index=[...activeSelect.native.options].findIndex(option=>!option.disabled&&option.textContent.toLowerCase().startsWith(activeSelect.typed.toLowerCase()));if(index>=0)highlightSelect(index);}});
